/* @lc app=leetcode id=3241 lang=kotlin */ class Solution { fun timeTaken(edges: Array<IntArray>): IntArray = (edges.size + 1).let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> IntArray(n).let { down -> order.reversed().forEach { v -> down[v] = g[v].orEmpty().filter { par[it] == v && it != 0 }.maxOfOrNull { down[it] + 2 - it % 2 } ?: 0 }.let { IntArray(n).let { up -> order.forEach { p -> g[p].orEmpty().filter { par[it] == p && it != 0 }.let { ch -> ch.map { down[it] + 2 - it % 2 }.sortedDescending().let { tops -> ch.forEach { v -> up[v] = 2 - p % 2 + maxOf(up[p], (down[v] + 2 - v % 2).let { mine -> if (tops[0] == mine) (tops.getOrNull(1) ?: 0) else tops[0] }) } } } }.let { IntArray(n) { maxOf(down[it], up[it]) } } } } } } } } } }